"""Original electrolyte chapter: calcium, magnesium and phosphate."""
from create_electrolytes import rows,q,HK,RC,GS,EL
from qbank_authoring import ref,finalize
HC=ref('Society for Endocrinology: Emergency Management of Acute Hypocalcaemia','https://pmc.ncbi.nlm.nih.gov/articles/PMC8117371/')
HM=ref('Endocrine Society: Hypercalcemia of Malignancy Guideline','https://academic.oup.com/jcem/article/108/3/507/6916871')
DN=ref('FDA: Prolia Severe Hypocalcemia Boxed Warning in Advanced CKD','https://www.fda.gov/drugs/drug-safety-communications/fda-adds-boxed-warning-increased-risk-severe-hypocalcemia-patients-advanced-chronic-kidney-disease')
RF=ref('ASPEN Consensus Recommendations for Refeeding Syndrome, 2020','https://doi.org/10.1002/ncp.10474')
TI=ref('Global Guidance for Tumor-Induced Osteomalacia, 2023','https://pmc.ncbi.nlm.nih.gov/articles/PMC10108006/')
q('A critically ill patient has hypoalbuminemia and an unexpected low total calcium. Which test best clarifies physiologically active calcium?', 'Direct ionized calcium measurement with appropriate sample handling',[
 ('Albumin-corrected calcium is invariably accurate in critical illness','Correction formulas can misclassify calcium status.'),('Urinary calcium alone','This does not directly measure circulating active calcium.'),('Total protein alone','It cannot establish the ionized fraction.')],
 'Bound calcium and active calcium are different', '**Albumin changes alter total calcium without necessarily changing ionized calcium.**',['Acid-base shifts also change binding.','Critical illness reduces reliability of simple correction formulas.'], '**Interpret the ionized result with pH and symptoms.**',['Sample exposure to air and delays can affect pH.','Do not give aggressive calcium solely from an unreliable corrected value.'],[['Total calcium','Includes bound fraction'],['Ionized calcium','Active fraction'],['Critical illness','Prefer direct assessment when needed']],[HC,RC],'clinical_scenario')
q('Acute respiratory alkalosis causes perioral tingling and carpopedal spasm despite normal total calcium. Which change explains the symptoms?', 'Increased calcium binding to albumin lowers ionized calcium',[
 ('A sudden rise in total body calcium','This does not explain tetany.'),('Immediate loss of all calcium in urine','A binding shift is the immediate mechanism.'),('Reduced albumin binding increases ionized calcium','Alkalosis increases binding, the opposite direction.')],
 'pH can change active calcium quickly', '**Alkalemia increases the negatively charged albumin binding sites available for calcium.**',['Total calcium can remain unchanged.','The effect can produce neuromuscular irritability.'], '**Treat the cause and assess severity.**',['Measure ionized calcium when indicated.','Avoid assuming that normal total calcium excludes symptomatic hypocalcemia.'],[['Alkalosis','More binding'],['Ionized fraction','Falls'],['Total calcium','May remain normal']],[HC,RC],'clinical_scenario')
q('A patient develops tetany and QT prolongation after thyroid surgery. Which immediate treatment is appropriate for severe symptomatic hypocalcemia?', 'Monitored intravenous calcium gluconate followed by reassessment and treatment of the cause',[
 ('Oral calcium alone despite severe symptoms','This is too slow for a significant acute emergency.'),('Calcitonin','It lowers calcium and is inappropriate.'),('A loop diuretic without calcium replacement','This may worsen calcium loss.')],
 'Symptoms determine emergency treatment', '**Severe acute hypocalcemia can cause seizures and arrhythmias.**',['Postsurgical hypoparathyroidism is a key possibility.','Check magnesium, phosphate, PTH and vitamin D as appropriate.'], '**Use a validated bolus and infusion protocol.**',['Society guidance uses 10–20 mL of 10% gluconate diluted and given over ten minutes with ECG monitoring.','Correct magnesium deficiency and arrange longer-term calcium/active vitamin D when indicated.'],[['Emergency','Tetany/seizures/QT changes'],['Initial treatment','IV calcium under monitoring'],['Cause','Evaluate PTH and magnesium']],[HC],'clinical_scenario')
q('Hypocalcemia is accompanied by hyperphosphatemia and an inappropriately low PTH. Which diagnosis is favored?', 'Hypoparathyroidism',[
 ('Isolated nutritional vitamin D deficiency with intact PTH response','PTH should usually rise and phosphate tends to be low or normal.'),('Primary hyperparathyroidism','This usually produces hypercalcemia with inappropriate PTH elevation.'),('PTH resistance as the best fit for low PTH','PTH resistance typically raises PTH.')],
 'Interpret PTH relative to the calcium', '**A low calcium should stimulate PTH secretion.**',['Failure of this response suggests gland dysfunction or severe magnesium disturbance.','Absent phosphaturic PTH action can raise phosphate.'], '**Review surgery, autoimmunity and magnesium.**',['Distinguish hormone deficiency from resistance.','Use active vitamin D and calcium strategies according to the cause and kidney function.'],[['Hypoparathyroidism','Low calcium/low or inappropriate PTH'],['PTH resistance','Low calcium/high PTH'],['Vitamin D deficiency','Secondary PTH elevation']],[HC])
q('Why can severe magnesium deficiency cause hypocalcemia that responds poorly to calcium alone?', 'It can impair both PTH secretion and PTH action',[
 ('It invariably increases PTH effectiveness','The physiological effect is opposite in severe deficiency.'),('It directly proves primary parathyroid carcinoma','That does not explain this pattern.'),('It eliminates all need for calcium in symptomatic patients','Acute calcium treatment may still be required.')],
 'Magnesium is necessary for normal calcium regulation', '**A functional hypoparathyroid state can accompany marked magnesium depletion.**',['Potassium depletion often coexists.','Serum values require interpretation with symptoms and losses.'], '**Correct magnesium as well as urgent calcium needs.**',['Adjust doses for reduced kidney function.','Reassess all three electrolytes during recovery.'],[['Magnesium deficit','PTH secretion/action impaired'],['Consequences','Low calcium and refractory low potassium'],['Treatment','Integrated replacement']],[HC,EL])
q('Hypercalcemia is confirmed. Which initial biochemical discriminator most efficiently separates major etiological groups?', 'PTH interpreted for appropriate suppression',[
 ('Serum sodium alone','This does not categorize the major calcium mechanisms.'),('A bone scan before any biochemical assessment in every case','PTH usually provides an important first branch.'),('Total cholesterol as the primary test','This is not the relevant discriminator.')],
 'High calcium should suppress normal PTH secretion', '**An elevated or inappropriately normal PTH suggests a PTH-dependent cause.**',['Suppressed PTH directs attention to malignancy, vitamin D mechanisms and other causes.','Medication, family and kidney context matter.'], '**Choose subsequent tests from the mechanism.**',['Do not order every rare-cause test indiscriminately.','Confirm genuine hypercalcemia when albumin or assay issues are present.'],[['PTH not suppressed','PTH-dependent pathway'],['PTH suppressed','PTH-independent pathway'],['Next tests','Mechanism directed']],[HM,HC])
q('A patient with malignancy has symptomatic calcium 15.5 mg/dL. Which initial strategy is recommended?', 'Appropriate IV hydration plus antiresorptive therapy, with short-term calcitonin for rapid initial effect',[
 ('Calcitonin alone indefinitely','Tachyphylaxis limits its sustained efficacy.'),('A thiazide diuretic as the principal calcium-lowering drug','Thiazides can increase calcium retention.'),('Withhold all therapy until definitive cancer surgery','Severe symptomatic hypercalcemia needs prompt stabilization.')],
 'Rapid and sustained treatments have different time courses', '**IV bisphosphonate or denosumab provides antiresorptive treatment for malignancy-associated hypercalcemia.**',['Calcitonin can bridge the slower onset.','Hydration is tailored to cardiac and kidney reserve.'], '**Limit calcitonin to about 48–72 hours.**',['Review kidney function when selecting antiresorptive therapy.','Definitive cancer treatment addresses the driver.'],[['Hydration','Correct volume deficit'],['Calcitonin','Rapid short-term effect'],['Antiresorptive','More sustained effect']],[HM],'clinical_scenario')
q('Hypercalcemia in sarcoidosis is most characteristically mediated by which process?', 'Extrarenal calcitriol production by activated macrophages',[
 ('Autonomous PTH secretion as the defining sarcoid mechanism','PTH is usually suppressed.'),('Obligate PTHrP secretion by every granuloma','Calcitriol production is the characteristic mechanism.'),('Complete absence of intestinal calcium absorption','Calcitriol increases absorption.')],
 'Granulomatous tissue can bypass normal renal calcitriol regulation', '**Macrophage 1-alpha-hydroxylase increases active vitamin D production.**',['Hypercalciuria can occur even without marked serum hypercalcemia.','Other granulomatous diseases and lymphoma can share this mechanism.'], '**Assess infection and the underlying disease before immunosuppression.**',['Glucocorticoids can reduce calcitriol-mediated hypercalcemia in appropriate cases.','Review calcium and vitamin D intake.'],[['PTH','Usually suppressed'],['Calcitriol','May be elevated'],['Mechanism','Extrarenal activation']],[HM])
q('A dialysis patient is being considered for osteoporosis treatment with Prolia. Which safety issue is especially important?', 'A boxed-warning risk of severe hypocalcemia in advanced CKD, especially with CKD-MBD',[
 ('Renal nonclearance guarantees absence of electrolyte toxicity','Lack of renal dose elimination does not remove hypocalcemia risk.'),('The drug is universally forbidden in every CKD stage','Selection requires an individualized specialist assessment rather than this blanket claim.'),('Calcium monitoring is unnecessary if the first dose was tolerated','Risk persists with treatment and changing clinical status.')],
 'Pharmacokinetics do not establish mineral safety', '**Denosumab suppresses osteoclastic calcium release.**',['Advanced CKD and underlying mineral-bone disease increase vulnerability.','Hypocalcemia can be prolonged and serious.'], '**Assess CKD-MBD and plan prevention and monitoring before treatment.**',['Use a clinician experienced in advanced CKD bone disease.','Review calcium and vitamin D strategy and discuss treatment alternatives.'],[['Exposure','Prolia/denosumab'],['High-risk setting','Advanced CKD and CKD-MBD'],['Requirement','Specialist assessment and monitoring']],[DN],'clinical_scenario')
q('Magnesium-containing laxatives are used repeatedly by a patient with severe kidney failure who develops hyporeflexia, bradycardia and respiratory depression. What is the likely diagnosis?', 'Symptomatic hypermagnesemia',[
 ('Isolated hypomagnesemia','This more often causes neuromuscular irritability and arrhythmias.'),('Uncomplicated hypophosphatemia as the complete explanation','The exposure and depressed reflexes favor magnesium toxicity.'),('Hyperthyroid periodic paralysis','The exposure pattern does not fit.')],
 'Reduced excretion makes ordinary magnesium products hazardous', '**Magnesium excess depresses neuromuscular and cardiac function.**',['Severe toxicity can cause hypotension and conduction block.','Medication history includes antacids and laxatives.'], '**Stop magnesium and provide supportive emergency treatment.**',['IV calcium can temporarily antagonize effects.','Severe toxicity with impaired clearance may require dialysis.'],[['Risk','Kidney failure plus magnesium load'],['Signs','Hyporeflexia and depression'],['Severe treatment','Support, calcium and possible dialysis']],[RC],'clinical_scenario')
q('What is the principal role of IV magnesium in torsades de pointes?', 'Treating the arrhythmia even when the measured serum magnesium is not low',[
 ('It must be withheld whenever magnesium is within the laboratory range','A normal level does not remove the arrhythmia indication.'),('It replaces defibrillation when the patient is pulseless','Pulseless arrhythmia requires the resuscitation algorithm.'),('It corrects every cause of a wide QRS including hyperkalemia by itself','Therapy must match the mechanism.')],
 'An arrhythmia indication differs from simple deficiency replacement', '**Magnesium is used for torsades associated with long QT.**',['Correct potassium and stop QT-prolonging triggers.','Bradycardia-dependent recurrence may need additional specialist therapy.'], '**Treat hemodynamic instability immediately.**',['Use electrical therapy when indicated.','Monitor for magnesium accumulation in kidney failure.'],[['Indication','Torsades/long-QT polymorphic VT'],['Adjunct actions','Potassium and trigger correction'],['Instability','Electrical resuscitation as indicated']],[RC,EL])
q('A patient receiving long-term proton-pump inhibitor therapy develops hypomagnesemia. Which mechanism is particularly implicated?', 'Reduced intestinal magnesium absorption',[
 ('A direct obligatory Fanconi syndrome in every patient','PPI-associated low magnesium is usually linked to absorption.'),('A consistent rise in serum magnesium from reduced gut uptake','Reduced uptake lowers stores.'),('Primary aldosterone excess is proven by the drug exposure','The exposure does not establish that endocrine diagnosis.')],
 'Drug-induced low magnesium need not be renal wasting', '**PPI-associated hypomagnesemia can recur with re-exposure.**',['Other causes include diarrhea, poor intake and renal losses.','Urine magnesium helps assess whether conservation is appropriate.'], '**Review the indication and consider a suitable alternative.**',['Replace magnesium according to severity and renal function.','Assess associated potassium and calcium abnormalities.'],[['PPI mechanism','Intestinal absorption impairment'],['Urine assessment','Conservation versus renal wasting'],['Management','Drug review plus replacement']],[EL])
q('During early feeding of a severely malnourished patient, phosphate, potassium and magnesium fall sharply. Which process explains this pattern?', 'Insulin-driven cellular uptake during refeeding',[
 ('A guaranteed new primary glomerulonephritis','The timing and multielectrolyte shifts favor refeeding.'),('Sodium-only depletion without intracellular metabolic change','This misses the central shift mechanism.'),('A harmless laboratory finding requiring no change in care','Severe shifts can cause organ dysfunction.')],
 'Calorie reintroduction can unmask depleted stores', '**Carbohydrate-driven insulin promotes intracellular electrolyte uptake.**',['Thiamine demand and fluid retention also increase.','Serum values can be initially normal despite depleted total stores.'], '**Use a risk-based nutrition and replacement protocol.**',['Give appropriate thiamine and monitor frequently.','Adjust calorie advancement and replace deficits under supervision.'],[['Timing','Hours to days after calories'],['Typical deficits','Phosphate, potassium and magnesium'],['Consequences','Cardiac, respiratory and neurological dysfunction']],[RF],'clinical_scenario')
q('Which complication is particularly characteristic of severe phosphate depletion?', 'Respiratory muscle weakness from impaired cellular energy metabolism',[
 ('Increased ATP availability','Phosphate depletion compromises energy metabolism.'),('A mandatory high serum calcium in every case','Calcium varies with the cause.'),('Protection against rhabdomyolysis','Rhabdomyolysis can occur in severe depletion.')],
 'Phosphate is essential for ATP and red-cell metabolism', '**Severe hypophosphatemia can cause weakness, rhabdomyolysis and respiratory failure.**',['Hemolysis and neurological dysfunction can also occur.','A serum level must be interpreted with clinical severity and the mechanism.'], '**Replace carefully when severe or symptomatic.**',['IV phosphate can precipitate hypocalcemia and requires renal-function-based precautions.','Milder stable deficits often permit oral therapy.'],[['Cell function','ATP and phosphorylated intermediates'],['Severe effects','Muscle and respiratory dysfunction'],['Replacement hazard','Hypocalcemia and overreplacement']],[EL,RF])
q('Bone pain and fractures are accompanied by persistent hypophosphatemia, renal phosphate wasting and inappropriately normal or high FGF23. Which diagnosis should be considered in an adult with new disease?', 'Tumor-induced osteomalacia',[
 ('Simple dietary phosphate deficiency with fully appropriate renal conservation','The kidney is wasting phosphate.'),('Untreated hypoparathyroidism as the best fit','That usually raises serum phosphate.'),('Isolated hyperventilation without chronic bone disease','An acute shift does not explain this chronic syndrome.')],
 'FGF23 can create a chronic phosphaturic syndrome', '**FGF23 reduces proximal phosphate reabsorption and calcitriol production.**',['A small phosphaturic mesenchymal tumor can be difficult to locate.','Inherited FGF23-related disorders remain part of the differential.'], '**Confirm the biochemical mechanism before tumor localization.**',['Complete resection can be curative when feasible.','Specialist medical treatment is available for unresectable or unlocalized disease.'],[['Phosphate','Low'],['Kidney response','Inappropriate wasting'],['FGF23','Inappropriately nonsuppressed']],[TI],'clinical_scenario')
q('A patient has low phosphate during acute respiratory alkalosis. Which mechanism can explain a rapid fall?', 'Intracellular phosphate shift stimulated by increased glycolysis',[
 ('Immediate proof of a large fixed renal phosphate leak','An acute shift can occur without renal wasting.'),('A universal rise in extracellular phosphate from alkalosis','The characteristic shift is into cells.'),('PTH deficiency as the necessary explanation','PTH deficiency tends to reduce phosphaturia.')],
 'Not every low serum phosphate represents the same total-body deficit', '**Intracellular alkalinization promotes glycolytic phosphate use.**',['The clinical setting and time course distinguish redistribution from chronic loss.','Coexisting malnutrition can add real depletion.'], '**Treat the precipitant and assess severity.**',['Follow serial phosphate during recovery.','Avoid unmonitored aggressive replacement when a shift is likely to reverse.'],[['Trigger','Respiratory alkalosis'],['Mechanism','Intracellular utilization/shift'],['Assessment','Duration and underlying stores']],[EL])
q('A patient with low phosphate excretes an inappropriately large fraction of filtered phosphate. What is the next mechanistic distinction?', 'Hormonal phosphaturia versus intrinsic proximal tubular dysfunction',[
 ('Assume a normal renal response to phosphate depletion','Appropriate conservation should reduce phosphate excretion.'),('Conclude that all phosphate loss is gastrointestinal','The measured pattern indicates renal loss.'),('Diagnose SIAD from phosphate alone','This is a separate water-balance disorder.')],
 'Identify why the proximal tubule is not conserving phosphate', '**PTH and FGF23 can drive phosphaturia.**',['Fanconi syndrome produces additional proximal losses such as glycosuria and bicarbonate wasting.','Fractional indices require concurrent serum and urine sampling and renal context.'], '**Use the associated biochemical pattern to target testing.**',['Check calcium, PTH and other proximal solutes.','Consider TmP/GFR in an appropriate chronic work-up.'],[['Hormonal','PTH or FGF23'],['Tubular','Fanconi or other proximal injury'],['Additional clues','Calcium, glucose and bicarbonate handling']],[TI,EL])
q('After chemotherapy, a patient develops hyperphosphatemia, hyperkalemia, hyperuricemia and hypocalcemia. Which mechanism best unifies the findings?', 'Tumor lysis with release of intracellular solutes and calcium-phosphate effects',[
 ('Refeeding syndrome','Refeeding typically lowers phosphate, potassium and magnesium.'),('Primary hyperparathyroidism','It usually raises calcium and lowers phosphate.'),('Isolated pseudohyperkalemia explains every finding','It cannot explain the full metabolic pattern.')],
 'The direction of multiple electrolyte changes identifies the syndrome', '**Rapid cell breakdown releases potassium and phosphate and increases purine-derived uric acid.**',['Calcium can fall as phosphate rises.','AKI can amplify the abnormalities.'], '**Treat as an oncological and metabolic emergency.**',['Monitor cardiac status and use a tumor-lysis protocol.','Avoid routine calcium for asymptomatic hypocalcemia when precipitation risk is high; severe symptoms need carefully judged treatment.'],[['Tumor lysis','High potassium/phosphate/urate'],['Refeeding','Low phosphate/potassium/magnesium'],['Calcium','May fall during lysis']],[RC,EL],'clinical_scenario')

if __name__=='__main__':finalize('Nephrology',8,'Potassium, Calcium, Magnesium and Phosphate Disorders','neph-electrolytes',rows,36)
